import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.*;

// Simulation of Asia Pacific Airport adhering strictly to thread separation and safety rules
public class AirportSimulation {
    // Basic & Additional Concurrency Facilities
    static final Semaphore airportGrounds = new Semaphore(3, true); // Capacity limit: max 3 planes
    static final Semaphore runway = new Semaphore(1, true);         // 1 Runway mutex (landing/takeoff)
    static final Semaphore gates = new Semaphore(3, true);          // 3 Concurrent docking gates
    static final Semaphore fuelTruck = new Semaphore(1, true);      // Exclusive refuelling truck
    static final AtomicInteger totalPlanesServed = new AtomicInteger(0);
    static final AtomicInteger totalPassengersBoarded = new AtomicInteger(0);
    static final List<Long> waitTimes = Collections.synchronizedList(new ArrayList<>());

    static class Plane extends Thread implements Comparable<Plane> {
        final int planeId;
        final boolean isEmergency;
        final int passengers;
        final long requestTime;

        Plane(int id, boolean emergency, int pax) {
            super("Thread-Plane-" + id + (emergency ? "-EMERGENCY" : ""));
            this.planeId = id;
            this.isEmergency = emergency;
            this.passengers = pax;
            this.requestTime = System.currentTimeMillis();
        }

        @Override
        public int compareTo(Plane other) {
            return Boolean.compare(other.isEmergency, this.isEmergency); // Priority to emergency
        }

        @Override
        public void run() {
            try {
                log("Requesting landing permission from ATC.");
                airportGrounds.acquire(); // Enforce <= 3 aircraft on airport grounds
                runway.acquire();         // Mutual exclusion for runway landing
                long waited = System.currentTimeMillis() - requestTime;
                waitTimes.add(waited);
                log("Landing on runway 1 (Wait time: " + waited + "ms). Coasting to gate...");
                Thread.sleep(120);

                gates.acquire();          // Dock at available gate
                runway.release();         // Clear runway immediately after coasting to gate
                log("Docked at gate. Concurrently disembarking " + passengers + " pax and cleaning.");
                Thread.sleep(180);

                fuelTruck.acquire();      // Exclusive refueling requirement
                log("Acquired exclusive refuelling truck. Refuelling aircraft...");
                Thread.sleep(140);
                fuelTruck.release();
                log("Refuelling completed; truck released. Embarking new passengers.");
                Thread.sleep(160);

                runway.acquire();         // Acquire runway for takeoff
                gates.release();          // Undock from gate
                log("Undocked from gate. Coasting to runway 1 for departure.");
                Thread.sleep(100);
                runway.release();         // Runway clear
                airportGrounds.release(); // Depart airport grounds
                log("Takeoff successful. Departed airport grounds into airspace.");

                totalPlanesServed.incrementAndGet();
                totalPassengersBoarded.addAndGet(passengers * 2);
            } catch (InterruptedException e) { 
                Thread.currentThread().interrupt(); 
            }
        }

        private void log(String message) {
            // Strict thread identity: current thread logs only for itself
            System.out.println(Thread.currentThread().getName() + " : " + message);
        }
    }

    public static void main(String[] args) throws InterruptedException {
        Thread atc = new Thread(() -> {
            System.out.println("Thread-ATC : Asia Pacific Airport ATC online. Ground cap: 3, Runway: 1, Gates: 3.");
        }, "Thread-ATC");
        atc.start();
        atc.join();

        // Congested scenario: Planes 1-2 occupy gates, 3-4 queue, Plane 5 arrives with emergency fuel shortage
        Plane[] fleet = {
            new Plane(1, false, 46), new Plane(2, false, 48),
            new Plane(3, false, 42), new Plane(4, false, 50),
            new Plane(5, true, 39),  // Emergency fuel shortage plane
            new Plane(6, false, 44)
        };

        for (Plane p : fleet) {
            p.start();
            Thread.sleep(150); // Staggered arrival (0-2s simulation scale)
        }
        for (Plane p : fleet) p.join();

        // ATC Sanity Checks and Performance Statistics
        System.out.println("\n--- ATC FINAL SANITY CHECK & STATISTICS ---");
        System.out.println("Thread-ATC : Sanity Check -> All 3 gates empty: " + (gates.availablePermits() == 3));
        System.out.println("Thread-ATC : Sanity Check -> Runway clear: " + (runway.availablePermits() == 1));
        System.out.println("Thread-ATC : Sanity Check -> Grounds empty: " + (airportGrounds.availablePermits() == 3));
        System.out.println("Thread-ATC : Total Planes Served: " + totalPlanesServed.get());
        System.out.println("Thread-ATC : Total Passengers Boarded: " + totalPassengersBoarded.get());
        long maxW = waitTimes.stream().mapToLong(v -> v).max().orElse(0);
        long minW = waitTimes.stream().mapToLong(v -> v).min().orElse(0);
        double avgW = waitTimes.stream().mapToLong(v -> v).average().orElse(0.0);
        System.out.printf("Thread-ATC : Wait Times -> Min: %dms, Max: %dms, Avg: %.2fms%n", minW, maxW, avgW);
        System.out.println("Thread-ATC : Simulation completed successfully under 60 seconds.");
    }
}
